CREATE OR REPLACE FUNCTION public.fn_ca_adjustment_under_10_9(p_tournament_id uuid, p_user_id uuid, p_amount numeric, p_reason text, p_migration text, p_actor_label text DEFAULT 'chip standard (Claude)'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
    RAISE EXCEPTION 'fn_ca_adjustment_under_10_9 is service only' USING ERRCODE = '42501';
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 200 THEN
    RAISE EXCEPTION 'a 10.9 adjustment carries the paragraph: at least 200 characters naming every affected player and why (got %)', length(btrim(COALESCE(p_reason, '')));
  END IF;
  IF COALESCE(p_migration, '') !~ '^\d{14}_[a-z0-9_]+$' THEN
    RAISE EXCEPTION 'a 10.9 adjustment names the migration that carries it (got %)', p_migration;
  END IF;
  IF p_reason NOT LIKE '%' || p_migration || '%' THEN
    RAISE EXCEPTION 'the reason must name the migration %', p_migration;
  END IF;
  INSERT INTO public.ca_manual_adjustments
    (actor, actor_label, approver, approver_label, reason, amount, target_kind, target_id, tournament_id, status, approved_at, decision_note, asset)
  VALUES
    ('00000000-0000-0000-0000-00000000c1a9', p_actor_label,
     '2d1cd6c3-5700-4af9-a271-d4863fdab20d', 'Dan, standing written approval under CLAUDE.md 10.9 (2026-09-02): agents settle real chips without asking when the five conditions hold',
     btrim(p_reason), round(p_amount, 2), 'player_wallet', p_user_id, p_tournament_id, 'approved', now(),
     'migration ' || p_migration, 'chips')
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_declare_ledger(p_category text, p_counterparty text, p_counterparty_entity uuid DEFAULT NULL::uuid, p_settlement_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_autoskip_tables text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t text;
BEGIN
  -- validate against the LIVE vocabulary so this can never lag a CHECK change
  IF p_category IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid = 'public.chip_ledger'::regclass
       AND conname = 'chip_ledger_category_check'
       AND pg_get_constraintdef(oid) LIKE '%''' || p_category || '''%') THEN
    RAISE EXCEPTION 'fn_ca_declare_ledger: category % is not in the ledger vocabulary - add it to chip_ledger_category_check FIRST, then declare it', p_category;
  END IF;
  IF p_counterparty IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid = 'public.chip_ledger'::regclass
       AND conname = 'chip_ledger_from_type_check'
       AND pg_get_constraintdef(oid) LIKE '%''' || p_counterparty || '''%') THEN
    RAISE EXCEPTION 'fn_ca_declare_ledger: counterparty % is not in the ledger vocabulary - add it to the from/to type CHECKs FIRST, then declare it', p_counterparty;
  END IF;

  PERFORM set_config('app.ledger_category', p_category, true);
  PERFORM set_config('app.ledger_counterparty', p_counterparty, true);
  PERFORM set_config('app.ledger_counterparty_entity',
                     COALESCE(p_counterparty_entity::text, ''), true);
  /* A COUNTERPARTY NAMES ITS COLUMN, AND A NEW DECLARATION FORGETS THE LAST
     ONE'S (2026-10-04). A union wallet holds six balances; the caller whose
     counterparty is one of them names it on app.ledger_counterparty_label
     after this call, and fn_ca_autoledger writes it on that side. */
  PERFORM set_config('app.ledger_counterparty_label', '', true);
  IF p_settlement_id IS NOT NULL THEN
    PERFORM set_config('app.ledger_settlement', p_settlement_id::text, true);
  END IF;
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM set_config('app.ledger_idempotency_key', p_idempotency_key, true);
  END IF;
  IF p_autoskip_tables IS NOT NULL THEN
    FOREACH v_t IN ARRAY p_autoskip_tables LOOP
      IF v_t !~ '^[a-z_]+$' THEN
        RAISE EXCEPTION 'fn_ca_declare_ledger: bad autoskip table name %', v_t;
      END IF;
      PERFORM set_config('app.ledger_autoskip_' || v_t, '1', true);
    END LOOP;
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.fn_credit_chips(p_club_id uuid, p_user_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_before numeric;
  v_after numeric;
  v_amt numeric := round(p_amount, 2);
BEGIN
  IF v_amt IS NULL OR v_amt <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  /* THE CALLER NAMES WHERE THE CHIPS COME FROM (2026-10-02,
     20261002140203). This primitive credits a wallet for a door it does not
     know. Without a declared counterparty the club_members journal books the
     leg against settlement_suspense and the commit check refuses the
     transaction; say so here, by name, before anything moves. */
  IF NULLIF(current_setting('app.ledger_counterparty', true), '') IS NULL
     AND COALESCE(current_setting('app.ledger_autoskip_club_members', true), '') <> '1' THEN
    RAISE EXCEPTION 'fn_credit_chips_requires_a_declared_counterparty'
      USING ERRCODE = '23514',
            DETAIL  = 'a player wallet credit with no app.ledger_counterparty would be journalled against settlement_suspense',
            HINT    = 'The calling door declares where the chips come from (fn_ca_declare_ledger) before it calls.';
  END IF;

  /* A category the calling door declared stands (2026-10-02,
     20261002165749: a shop refund is a refund, not player funding). */
  PERFORM set_config('app.ledger_category',
    COALESCE(NULLIF(current_setting('app.ledger_category', true), ''), 'player_funding'), true);

  SELECT COALESCE(chip_balance, 0) INTO v_before
  FROM club_members
  WHERE club_id = p_club_id AND user_id = p_user_id FOR UPDATE;

  IF v_before IS NULL THEN
    INSERT INTO club_members (club_id, user_id, role, chip_balance, joined_at, created_at, updated_at, status, is_active)
    VALUES (p_club_id, p_user_id, 'player', v_amt, NOW(), NOW(), NOW(), 'active', true)
    ON CONFLICT (club_id, user_id) DO UPDATE
      SET chip_balance = COALESCE(club_members.chip_balance, 0) + EXCLUDED.chip_balance,
          updated_at = NOW();
    v_before := 0;
    v_after := v_amt;
  ELSE
    /* ZERO-DRIFT (2026-08-31): was + p_amount::integer - the balance moved by
       a truncated amount while the journal recorded the full numeric amount,
       destroying fractions on every fractional call. */
    UPDATE club_members
    SET chip_balance = COALESCE(chip_balance, 0) + v_amt,
        updated_at = NOW()
    WHERE club_id = p_club_id AND user_id = p_user_id;
    v_after := v_before + v_amt;
  END IF;

  INSERT INTO chip_transactions (
    id, club_id, from_user_id, to_user_id, amount,
    transaction_type, notes, metadata, balance_after, created_at
  ) VALUES (
    gen_random_uuid(), p_club_id, NULL, p_user_id, v_amt,
    COALESCE(p_metadata->>'transaction_type', 'chip_credit'),
    COALESCE(p_reason, 'Chip credit'), p_metadata, v_after, NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'amount', v_amt,
    'balance_before', v_before,
    'balance_after', v_after
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_union_debit_wallet(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text DEFAULT NULL::text, p_club_id uuid DEFAULT NULL::uuid, p_period_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid, p_op_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_prior jsonb;
  v_res jsonb;
BEGIN
  IF p_op_id IS NULL THEN
    RETURN public.fn_union_debit_wallet_zd3core(
      p_union_id, p_wallet, p_amount, p_tx_type, p_club_id, p_period_id, p_notes, p_created_by);
  END IF;

  SELECT result INTO v_prior
    FROM public.ca_op_claims
   WHERE op_id = p_op_id AND fn_name = 'fn_union_debit_wallet';
  IF FOUND AND v_prior IS NOT NULL THEN
    RETURN v_prior || jsonb_build_object('replayed', true, 'op_id', p_op_id);
  ELSIF FOUND THEN
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_union_debit_wallet';
  END IF;

  INSERT INTO public.ca_op_claims (op_id, fn_name)
  VALUES (p_op_id, 'fn_union_debit_wallet');

  v_res := public.fn_union_debit_wallet_zd3core(
    p_union_id, p_wallet, p_amount, p_tx_type, p_club_id, p_period_id, p_notes, p_created_by);

  IF COALESCE(v_res->>'success', '') = 'true' THEN
    UPDATE public.ca_op_claims
       SET result = v_res, finalized_at = now()
     WHERE op_id = p_op_id AND fn_name = 'fn_union_debit_wallet';
  ELSE
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_union_debit_wallet';
  END IF;

  RETURN v_res;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_union_debit_wallet_zd3core(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text, p_club_id uuid, p_period_id uuid, p_notes text, p_created_by uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_wallet_column text;
  v_before numeric;
  v_after numeric;
  v_sql text;
  v_cat text;
  v_cp text;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  v_wallet_column := CASE lower(p_wallet)
    WHEN 'chip' THEN 'chip_balance'
    WHEN 'chip_balance' THEN 'chip_balance'
    WHEN 'rake' THEN 'rake_wallet'
    WHEN 'rake_wallet' THEN 'rake_wallet'
    WHEN 'bbj' THEN 'bbj_wallet'
    WHEN 'bbj_wallet' THEN 'bbj_wallet'
    WHEN 'promo' THEN 'promo_wallet'
    WHEN 'promo_wallet' THEN 'promo_wallet'
    WHEN 'insurance' THEN 'insurance_wallet'
    WHEN 'insurance_wallet' THEN 'insurance_wallet'
    ELSE NULL
  END;

  IF v_wallet_column IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown wallet: ' || p_wallet);
  END IF;

  v_sql := format('SELECT COALESCE(%I,0) FROM union_wallets WHERE union_id = $1 FOR UPDATE', v_wallet_column);
  EXECUTE v_sql INTO v_before USING p_union_id;

  IF v_before IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'union wallet not found');
  END IF;

  IF v_before < p_amount THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'insufficient balance',
      'wallet', v_wallet_column, 'balance', v_before, 'requested', p_amount
    );
  END IF;

  SELECT category, counterparty INTO v_cat, v_cp
    FROM public.fn_ca_union_wallet_ledger_shape(p_tx_type);
  IF v_cp IS NOT NULL THEN
    PERFORM public.fn_ca_declare_ledger(v_cat, v_cp);
  END IF;

  v_sql := format('UPDATE union_wallets SET %I = %I - $1, updated_at = NOW() WHERE union_id = $2 RETURNING %I',
                  v_wallet_column, v_wallet_column, v_wallet_column);
  EXECUTE v_sql INTO v_after USING p_amount, p_union_id;

  IF v_cp IS NOT NULL THEN
    PERFORM set_config('app.ledger_counterparty', '', true);
    PERFORM set_config('app.ledger_category', '', true);
    PERFORM set_config('app.ledger_counterparty_entity', '', true);
  END IF;

  INSERT INTO union_wallet_transactions (
    id, union_id, wallet, direction, amount, balance_after,
    tx_type, club_id, period_id, notes, created_by, created_at
  ) VALUES (
    gen_random_uuid(), p_union_id, v_wallet_column, 'debit', p_amount, v_after,
    COALESCE(p_tx_type, 'debit'), p_club_id, p_period_id, p_notes, p_created_by, NOW()
  );

  RETURN jsonb_build_object(
    'success', true, 'amount', p_amount,
    'wallet', v_wallet_column,
    'balance_before', v_before, 'balance_after', v_after
  );
END;
$function$

